34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.controller.CityOwnerLimitExceededException;
40	import org.springframework.samples.petclinic.rest.controller.DuplicateHouseholdException;
41	import org.springframework.samples.petclinic.rest.controller.DuplicateTelephoneException;
42	import org.springframework.samples.petclinic.rest.controller.InvalidEmailException;
43	import org.springframework.samples.petclinic.rest.controller.InvalidTelephoneException;
44	import org.springframework.samples.petclinic.rest.controller.RequiredFieldsMissingException;
45	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
46	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.PetDto;
48	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitDto;
50	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
51	import org.springframework.samples.petclinic.service.ClinicService;
52	import org.springframework.security.access.prepost.PreAuthorize;
53	import org.springframework.web.bind.annotation.CrossOrigin;
54	import org.springframework.web.bind.annotation.RequestMapping;
55	import org.springframework.web.bind.annotation.RestController;
56	import org.springframework.web.util.UriComponentsBuilder;
57	
58	import jakarta.transaction.Transactional;
59	
60	/**
61	 * @author Vitaliy Fedoriv
62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /**
70	     * Pragmatic syntactic check for an email address: a non-empty local part, a single {@code @}, and a
71	     * domain with at least one dot and a two-or-more-letter final label. Whitespace is not permitted.
72	     */
73	    private static final Pattern EMAIL_PATTERN =
74	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@.]{2,}$");
75	
76	    private final ClinicService clinicService;
77	
78	    private final OwnerMapper ownerMapper;
79	
80	    private final PetMapper petMapper;
81	
82	    private final VisitMapper visitMapper;
83	
84	    public OwnerRestControllerV1(ClinicService clinicService,
85	                                 OwnerMapper ownerMapper,
86	                                 PetMapper petMapper,
87	                                 VisitMapper visitMapper) {
88	        this.clinicService = clinicService;
89	        this.ownerMapper = ownerMapper;
90	        this.petMapper = petMapper;
91	        this.visitMapper = visitMapper;
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
97	        Collection<Owner> owners;
98	        if (lastName != null) {
99	            owners = this.clinicService.findOwnerByLastName(lastName);
100	        } else {
101	            owners = this.clinicService.findAllOwners();
102	        }
103	        if (owners.isEmpty()) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
112	        Owner owner = this.clinicService.findOwnerById(ownerId);
113	        if (owner == null) {
114	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
115	        }
116	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
122	        rejectMissingOrBlankFields(ownerFieldsDto);
123	        HttpHeaders headers = new HttpHeaders();
124	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
125	        owner.setAddress(normalizeAddress(owner.getAddress()));
126	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
127	        owner.setEmail(normalizeEmail(owner.getEmail()));
128	        if (owner.getRegistrationDate() == null) {
129	            owner.setRegistrationDate(LocalDate.now());
130	        }
131	        rejectDuplicateTelephone(owner.getTelephone());
132	        rejectCityAtCapacity(owner.getCity());
133	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
134	            assignHousehold(owner);
135	        } else {
136	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
137	        }
138	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
139	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
140	        this.clinicService.saveOwner(owner);
141	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
142	        headers.setLocation(UriComponentsBuilder.newInstance()
143	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
144	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
150	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
151	        if (currentOwner == null) {
152	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
153	        }
154	        currentOwner.setAddress(ownerFieldsDto.getAddress());
155	        currentOwner.setCity(ownerFieldsDto.getCity());
156	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
157	        currentOwner.setLastName(ownerFieldsDto.getLastName());
158	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
159	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
160	        this.clinicService.saveOwner(currentOwner);
161	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
162	    }
163	
164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Transactional
166	    @Override
167	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
168	        Owner owner = this.clinicService.findOwnerById(ownerId);
169	        if (owner == null) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        this.clinicService.deleteOwner(owner);
173	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
179	        Owner owner = this.clinicService.findOwnerById(ownerId);
180	        if (owner == null) {
181	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
182	        }
183	        HttpHeaders headers = new HttpHeaders();
184	        Pet pet = petMapper.toPet(petFieldsDto);
185	        owner.setId(ownerId);
186	        pet.setOwner(owner);
187	        pet.getType().setName(null);
188	        this.clinicService.savePet(pet);
189	        PetDto petDto = petMapper.toPetDto(pet);
190	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
191	            .buildAndExpand(pet.getId()).toUri());
192	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
193	    }
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Override
197	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
198	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
199	        if (currentOwner != null) {
200	            Pet currentPet = this.clinicService.findPetById(petId);
201	            if (currentPet != null) {
202	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
203	                currentPet.setName(petFieldsDto.getName());
204	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
205	                this.clinicService.savePet(currentPet);
206	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
207	            }
208	        }
209	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
210	    }
211	
212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Override
214	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
215	        HttpHeaders headers = new HttpHeaders();
216	        Visit visit = visitMapper.toVisit(visitFieldsDto);
217	        Pet pet = new Pet();
218	        pet.setId(petId);
219	        visit.setPet(pet);
220	        this.clinicService.saveVisit(visit);
221	        VisitDto visitDto = visitMapper.toVisitDto(visit);
222	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
223	            .buildAndExpand(visit.getId()).toUri());
224	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
225	    }
226	
227	
228	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
229	    @Override
230	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
231	        Owner owner = this.clinicService.findOwnerById(ownerId);
232	        if (owner != null) {
233	            Pet pet = owner.getPet(petId);
234	            if (pet != null) {
235	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
236	            }
237	        }
238	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
239	    }
240	
241	    /**
242	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
243	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
244	     *
245	     * @param fields the submitted owner fields
246	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
247	     *                                        {@code null} or blank, or if address is blank after
248	     *                                        normalization
249	     */
250	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
251	        List<String> missing = new ArrayList<>();
252	        if (isBlank(fields.getFirstName())) {
253	            missing.add("firstName");
254	        }
255	        if (isBlank(fields.getLastName())) {
256	            missing.add("lastName");
257	        }
258	        if (isBlank(normalizeAddress(fields.getAddress()))) {
259	            missing.add("address");
260	        }
261	        if (isBlank(fields.getCity())) {
262	            missing.add("city");
263	        }
264	        if (isBlank(fields.getTelephone())) {
265	            missing.add("telephone");
266	        }
267	        if (!missing.isEmpty()) {
268	            throw new RequiredFieldsMissingException(missing);
269	        }
270	    }
271	
272	    private boolean isBlank(String value) {
273	        return value == null || value.isBlank();
274	    }
275	
276	    /**
277	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
278	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
279	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
280	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
281	     *
282	     * @param telephone the raw telephone value from the request
283	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
284	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
285	     */
286	    private String normalizeTelephone(String telephone) {
287	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
288	        String digits;
289	        if (cleaned.startsWith("+")) {
290	            digits = cleaned.substring(1);
291	        } else {
292	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
293	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
294	            digits = "61" + national;
295	        }
296	        if (!digits.matches("[0-9]{8,15}")) {
297	            throw new InvalidTelephoneException(cleaned);
298	        }
299	        return "+" + digits;
300	    }
301	
302	    /**
303	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
304	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
305	     * lower-cased.
306	     *
307	     * @param email the raw email value from the request, or {@code null} if omitted
308	     * @return the lower-cased email, or {@code null} if none was supplied
309	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
310	     */
311	    private String normalizeEmail(String email) {
312	        if (email == null) {
313	            return null;
314	        }
315	        String trimmed = email.strip();
316	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
317	            throw new InvalidEmailException(email);
318	        }
319	        return trimmed.toLowerCase(Locale.ROOT);
320	    }
321	
322	    /**
323	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
324	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
325	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
326	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
327	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
328	     *
329	     * @param address the raw address value from the request (may be {@code null})
330	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
331	     */
332	    private String normalizeAddress(String address) {
333	        if (address == null) {
334	            return "";
335	        }
336	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
337	        if (collapsed.isEmpty()) {
338	            return "";
339	        }
340	        String[] tokens = collapsed.split(" ");
341	        StringBuilder sb = new StringBuilder(collapsed.length());
342	        for (int i = 0; i < tokens.length; i++) {
343	            if (i > 0) {
344	                sb.append(' ');
345	            }
346	            sb.append(expandAddressAbbreviation(tokens[i]));
347	        }
348	        return sb.toString();
349	    }
350	
351	    /**
352	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
353	     * returns the token unchanged when it is not a recognised abbreviation.
354	     *
355	     * @param token an upper-cased whole-word address token
356	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
357	     */
358	    private String expandAddressAbbreviation(String token) {
359	        return switch (token) {
360	            case "ST" -> "STREET";
361	            case "RD" -> "ROAD";
362	            case "AVE" -> "AVENUE";
363	            default -> token;
364	        };
365	    }
366	
367	    /**
368	     * Rejects a create request whose normalized telephone is already used by another owner. Owners store
369	     * their telephone in normalized E.164 form, so an exact string comparison of E.164 values is sufficient.
370	     *
371	     * @param telephone the normalized (E.164) telephone of the owner being created
372	     * @throws DuplicateTelephoneException if any existing owner already uses the telephone
373	     */
374	    /**
375	     * Builds the customer code assigned to a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
376	     * where {@code CITY3} is the upper-cased first three letters of the owner's city, {@code LAST3} the
377	     * upper-cased first three letters of the owner's last name, and {@code NNNN} a per-city 4-digit
378	     * zero-padded sequence equal to one more than the number of owners already in that city (e.g.
379	     * {@code 'SYD-SMI-0007'}). The code is computed before the new owner is persisted, so the count excludes
380	     * it. Cities are matched case-insensitively so that owners sharing a {@code CITY3} prefix share a sequence.
381	     *
382	     * @param city the owner's city
383	     * @param lastName the owner's last name
384	     * @return the assigned customer code
385	     */
386	    private String generateCustomerCode(String city, String lastName) {
387	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
388	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
389	        int sequence = (int) this.clinicService.findAllOwners().stream()
390	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
391	            .count() + 1;
392	        return String.format("%s-%s-%04d", city3, last3, sequence);
393	    }
394	
395	    /**
396	     * Counts how many existing owners already share the given first name and last name, compared
397	     * case-insensitively. The count is taken before the new owner is persisted, so it excludes the
398	     * owner being created.
399	     *
400	     * @param firstName the first name of the owner being created
401	     * @param lastName the last name of the owner being created
402	     * @return the number of existing owners with the same first and last name (case-insensitively)
403	     */
404	    private int countNamesakes(String firstName, String lastName) {
405	        return (int) this.clinicService.findAllOwners().stream()
406	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
407	                && lastName.equalsIgnoreCase(existing.getLastName()))
408	            .count();
409	    }
410	
411	    /**
412	     * The maximum number of owners permitted in a single city. A create request whose city already
413	     * holds this many owners is rejected.
414	     */
415	    private static final int CITY_OWNER_LIMIT = 50;
416	
417	    /**
418	     * Rejects a create request whose city already contains {@link #CITY_OWNER_LIMIT} or more owners.
419	     * Cities are matched case-insensitively, mirroring the per-city customer-code sequence, so owners
420	     * differing only in the casing of their city share one capacity pool. The count is taken before the
421	     * new owner is persisted, so it excludes the owner being created.
422	     *
423	     * @param city the city of the owner being created
424	     * @throws CityOwnerLimitExceededException if the city already holds the maximum number of owners
425	     */
426	    private void rejectCityAtCapacity(String city) {
427	        long existing = this.clinicService.findAllOwners().stream()
428	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
429	            .count();
430	        if (existing >= CITY_OWNER_LIMIT) {
431	            throw new CityOwnerLimitExceededException(city, CITY_OWNER_LIMIT);
432	        }
433	    }
434	
435	    private void rejectDuplicateTelephone(String telephone) {
436	        boolean taken = this.clinicService.findAllOwners().stream()
437	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
438	        if (taken) {
439	            throw new DuplicateTelephoneException(telephone);
440	        }
441	    }
442	
443	    /**
444	     * Rejects a create request whose owner shares both last name and address with an existing owner.
445	     * Last name and address are compared case-insensitively with runs of whitespace collapsed to a
446	     * single space and leading/trailing whitespace removed, so cosmetic differences (extra spaces,
447	     * differing case) still count as the same household.
448	     *
449	     * @param lastName the last name of the owner being created
450	     * @param address the address of the owner being created
451	     * @throws DuplicateHouseholdException if an existing owner has the same last name and address
452	     */
453	    private void rejectDuplicateHousehold(String lastName, String address) {
454	        String normalizedLastName = normalizeForComparison(lastName);
455	        String normalizedAddress = normalizeForComparison(address);
456	        boolean taken = this.clinicService.findAllOwners().stream()
457	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
458	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())));
459	        if (taken) {
460	            throw new DuplicateHouseholdException(lastName, address);
461	        }
462	    }
463	
464	    /**
465	     * Assigns the owner being created into a shared household. When at least one existing owner has the
466	     * same last name and address (compared with {@link #normalizeForComparison}), the joining owner and
467	     * those existing owners are all given the same stable {@code householdId}. An existing member's id is
468	     * reused when present; otherwise a deterministic id derived from the household's last name and address
469	     * is minted, so independently created members of the same household converge on one value. When no
470	     * existing owner shares the household, no id is assigned (the owner simply founds a new address).
471	     *
472	     * @param owner the owner being created, already opted in via {@code sharesHousehold}
473	     */
474	    private void assignHousehold(Owner owner) {
475	        String normalizedLastName = normalizeForComparison(owner.getLastName());
476	        String normalizedAddress = normalizeForComparison(owner.getAddress());
477	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
478	            .filter(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
479	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())))
480	            .toList();
481	        if (housemates.isEmpty()) {
482	            return;
483	        }
484	        String householdId = housemates.stream()
485	            .map(Owner::getHouseholdId)
486	            .filter(id -> id != null && !id.isBlank())
487	            .findFirst()
488	            .orElseGet(() -> householdIdFor(normalizedLastName, normalizedAddress));
489	        owner.setHouseholdId(householdId);
490	        for (Owner housemate : housemates) {
491	            if (!householdId.equals(housemate.getHouseholdId())) {
492	                housemate.setHouseholdId(householdId);
493	                this.clinicService.saveOwner(housemate);
494	            }
495	        }
496	    }
497	
498	    /**
499	     * Derives a stable household identifier from the normalized last name and address of a household, as
500	     * the first 16 hex characters of the SHA-256 digest of {@code '<lastName>|<address>'}. The value is
501	     * deterministic, so any owner independently joining the same household computes the same identifier.
502	     *
503	     * @param normalizedLastName the household's last name, already normalized for comparison
504	     * @param normalizedAddress the household's address, already normalized for comparison
505	     * @return a stable, shareable household identifier
506	     */
507	    private String householdIdFor(String normalizedLastName, String normalizedAddress) {
508	        String key = normalizedLastName + "|" + normalizedAddress;
509	        try {
510	            byte[] digest = MessageDigest.getInstance("SHA-256")
511	                .digest(key.getBytes(StandardCharsets.UTF_8));
512	            StringBuilder sb = new StringBuilder(digest.length * 2);
513	            for (byte b : digest) {
514	                sb.append(String.format("%02x", b));
515	            }
516	            return sb.substring(0, 16);
517	        } catch (NoSuchAlgorithmException e) {
518	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
519	        }
520	    }
521	
522	    /**
523	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
524	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
525	     * lower-cased.
526	     *
527	     * @param value the raw value to normalize (may be {@code null})
528	     * @return the normalized value, or an empty string when {@code value} is {@code null}
529	     */
530	    private String normalizeForComparison(String value) {
531	        if (value == null) {
532	            return "";
533	        }
534	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
535	    }
536	}
